class Solution:
    def sumSortableIntegers(self, nums):
        n = len(nums)
        s = sorted(nums)
        total = 0
        for k in range(1, n + 1):
            if n % k:
                continue
            ok = True
            for b in range(0, n, k):
                if sorted(nums[b:b + k]) != s[b:b + k]:
                    ok = False
                    break
            if ok:
                total += k
        return total

