class Solution {
public:
    long long sumSortableIntegers(vector<int>& nums) {
        int n = nums.size();
        vector<int> s = nums;
        sort(s.begin(), s.end());
        long long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k) continue;
            bool ok = true;
            for (int b = 0; b + k <= n && ok; b += k) {
                vector<int> blk(nums.begin() + b, nums.begin() + b + k);
                sort(blk.begin(), blk.end());
                for (int t = 0; t < k; t++)
                    if (blk[t] != s[b + t]) { ok = false; break; }
            }
            if (ok) total += k;
        }
        return total;
    }
};

