        int n = nums.length;
        int[] s = nums.clone();
        java.util.Arrays.sort(s);
        long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            boolean ok = true;
            for (int b = 0; b + k <= n && ok; b += k) {
                int[] blk = java.util.Arrays.copyOfRange(nums, b, b + k);
                java.util.Arrays.sort(blk);
                for (int t = 0; t < k; t++)
                    if (blk[t] != s[b + t]) { ok = false; break; }
            }
            if (ok) total += k;
        }
        return total;
    }
}

