class Solution:
    def sumSortableIntegers(self, nums):
        n = len(nums)
        order = sorted(range(n), key=lambda i: nums[i])
        rank = [0] * n
        for r, i in enumerate(order):
            rank[i] = r
        total = 0
        for k in range(1, n + 1):
            if n % k:
                continue
            ok = True
            for b in range(0, n, k):
                if sorted(rank[b:b + k]) != list(range(b, b + k)):
                    ok = False
                    break
            if ok:
                total += k
        return total

