class Solution {
public:
    long long sumSortableIntegers(vector<int>& nums) {
        int n = nums.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        stable_sort(idx.begin(), idx.end(), [&](int a, int b) { return nums[a] < nums[b]; });
        vector<int> rank(n);
        for (int r = 0; r < n; r++) rank[idx[r]] = r;
        long long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k) continue;
            bool ok = true;
            for (int b = 0; b + k <= n && ok; b += k) {
                vector<char> seen(k, 0);
                for (int t = 0; t < k; t++) {
                    int r = rank[b + t] - b;
                    if (r < 0 || r >= k || seen[r]) { ok = false; break; }
                    seen[r] = 1;
                }
            }
            if (ok) total += k;
        }
        return total;
    }
};

