class Solution {
    public long sumSortableIntegers(int[] nums) {
        int n = nums.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> Integer.compare(nums[a], nums[b]));
        int[] rank = new int[n];
        for (int r = 0; r < n; r++) rank[idx[r]] = r;
        long total = 0;
        for (int k = 1; k <= n; k++) {
            if (n % k != 0) continue;
            boolean ok = true;
            for (int b = 0; b + k <= n && ok; b += k) {
                boolean[] seen = new boolean[k];
                for (int t = 0; t < k; t++) {
                    int r = rank[b + t] - b;
                    if (r < 0 || r >= k || seen[r]) { ok = false; break; }
                    seen[r] = true;
                }
            }
            if (ok) total += k;
        }
        return total;
    }
}

