var sumSortableIntegers = function(nums) {
    const n = nums.length;
    const idx = [...Array(n).keys()].sort((a, b) => nums[a] - nums[b]);
    const rank = new Array(n);
    idx.forEach((v, r) => rank[v] = r);
    let total = 0;
    for (let k = 1; k <= n; k++) {
        if (n % k) continue;
        let ok = true;
        for (let b = 0; b + k <= n && ok; b += k) {
            const seen = new Set();
            for (let t = 0; t < k; t++) {
                const r = rank[b + t] - b;
                if (r < 0 || r >= k || seen.has(r)) { ok = false; break; }
                seen.add(r);
            }
        }
        if (ok) total += k;
    }
    return total;
};
